// Router: nhan Message Envelope (spec ARCHITECTURE.md muc 3) tu Gateway,
// tinh route/command/params/taskId, dong thoi TAI TAO lai originalData.message /
// originalData.callback_query giong shape Telegram cu, de cac node Code/Set
// duoc tai su dung nguyen ven (Prepare Search, noresult, extract output...)
// van hoat dong binh thuong qua $('Phan tich lenh').item.json.originalData....
const items = $input.all();

function parseCommand(rawText) {
  let command = '';
  let params = '';
  if ((rawText || '').startsWith('/')) {
    const parts = rawText.trim().split(/\s+/);
    command = parts[0].toLowerCase();
    params = parts.slice(1).join(' ');
  } else {
    params = rawText || '';
  }
  return { command, params };
}

function computeRoute(command, params) {
  if (params.startsWith('chitiet_')) {
    return { route: 'chitiet', params: 'chitiet', taskId: params.replace('chitiet_', '').trim() };
  }
  if (command === '/task') return { route: 'task', params, taskId: null };
  if (command === '/help' || command === '/start') return { route: 'help', params, taskId: null };
  if (command === '/taotask') return { route: 'taotask', params, taskId: null };
  if (command === '/sync') return { route: 'sync', params, taskId: null };  // MOI: admin config List dong bo
  if (!command && params) return { route: 'free_text', params, taskId: null };
  return { route: 'unknown_command', params, taskId: null };
}

return items.map(it => {
  const env = it.json ?? {};
  const isCallback = env.kind === 'callback';
  const rawText = isCallback ? (env.callback?.data || '') : (env.text || '');

  let route, command = '', params = '', taskId = null;

  if (isCallback) {
    if (rawText.startsWith('chitiet_')) {
      route = 'chitiet'; taskId = rawText.replace('chitiet_', '').trim(); params = 'chitiet';
    } else if (rawText.startsWith('view_file:')) {
      route = 'view_file'; taskId = rawText.replace('view_file:', '').trim(); params = 'view_file';
    } else if (rawText.startsWith('sync_folder:')) {
      route = 'sync_folder'; params = rawText.replace('sync_folder:', '').trim(); // = folder_id
    } else if (rawText.startsWith('sync_list:')) {
      route = 'sync_list'; params = rawText.replace('sync_list:', '').trim(); // = "<list_id>:<folder_id>"
    } else if (rawText.startsWith('sync_now:')) {
      route = 'sync_now'; params = rawText.replace('sync_now:', '').trim(); // = list_id
    } else if (rawText === 'sync_later') {
      route = 'sync_later'; params = '';
    } else {
      route = 'unknown_command'; params = rawText;
    }
  } else {
    const parsed = parseCommand(rawText);
    command = parsed.command;
    const r = computeRoute(parsed.command, parsed.params);
    route = r.route; params = r.params; taskId = r.taskId;
  }

  // Tai tao legacy shape (.message / .callback_query) de code cu doc duoc
  const legacyMessage = !isCallback ? {
    text: env.text || '',
    chat: { id: env.chat_id },
    message_id: env.raw?.message_id ?? null,
    from: { id: env.user_id, username: env.username }
  } : undefined;
  const legacyCallback = isCallback ? {
    id: env.callback?.id,
    data: env.callback?.data,
    message: { chat: { id: env.chat_id }, message_id: env.callback?.message_id }
  } : undefined;

  return {
    json: {
      route, command, params, taskId,
      chatId: env.chat_id,
      messageId: isCallback ? (env.callback?.message_id ?? null) : (env.raw?.message_id ?? null),
      isCallback,
      originalData: {
        ...env,
        message: legacyMessage,
        callback_query: legacyCallback
      }
    }
  };
});

const allItems = $input.all();
const normalize = (s) =>
  s.normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\u0111/g, 'd')
    .replace(/\u0110/g, 'D')
    .toLowerCase();
const processedData = allItems.map(({ json: item }) => {
  const raw = item.params || '';
  const words = raw.trim().split(/\s+/).filter(Boolean);
  const keywords = words.flatMap(word => [word, normalize(word), normalize(word).toLowerCase()]);
  return {
    json: {
      ...item,
      searchKeywords: [...new Set(keywords)],
      originalText: raw,
      originalText_khong_dau: normalize(raw),
    }
  };
});
return processedData;

const normalize = s => s
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/\u0111/g, 'd')
  .replace(/\u0110/g, 'D')
  .toLowerCase();

const results = $input.all().map(item => {
  const task = item.json;
  const keywords = Array.isArray(task.searchKeywords) ? task.searchKeywords.map(kw => normalize(kw)) : [];
  const name = normalize(task.name || '');
  const nameWords = name.split(/\s+/);
  const matchWords = keywords.filter(kw => nameWords.includes(kw));
  const match_score = matchWords.length;
  const fullMatch = match_score === keywords.length && keywords.length > 0;
  return { json: { ...task, match_score, max_score: keywords.length, fullMatch } };
});
return results;

const inputItems = $input.all();
const originalContext = inputItems.find(i => i.json.chatId);
const chatId = originalContext?.json?.chatId || null;
const messageId = originalContext?.json?.messageId || null;
const searchText = originalContext?.json?.originalText || '';
const all = inputItems.filter(i => i.json.id).map(i => i.json);
const fullMatches = all.filter(i => i.fullMatch === true);
const partialMatches = all.filter(i => i.fullMatch !== true);

const escapeHtml = (text) =>
  text?.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;") || '';

const cleanLink = (link) => link?.replace(/^'+|'+$/g, '').replace(/[{}]/g, '').trim() || '';

const botUsername = 'Elite_clickup_bot';

const formatTask = (task, index) => {
  const link = `https://t.me/${botUsername}?start=chitiet_${task.id}`;
  const matchScore = task.match_score !== undefined ? ` + (${task.match_score})` : '';
  const onedrive = task.onedrive_link ? cleanLink(task.onedrive_link) : '';
  const clickupUrl = task.url ? cleanLink(task.url) : '';
  return (
`<b>${index + 1}.</b> <a href="${link}">${escapeHtml(task.name)}</a>
\u251c Tr\u1ea1ng th\u00e1i: ${escapeHtml(task.status) || 'Kh\u00f4ng r\u00f5'}${matchScore}
\u251c List: ${task.list ? escapeHtml(task.list) : 'Kh\u00f4ng r\u00f5'}
\u251c Ph\u1ee5 tr\u00e1ch: ${escapeHtml(task.phu_trach?.trim()) || 'Kh\u00f4ng r\u00f5'}
${onedrive ? `\u251c \ud83d\udcc1 <a href="${onedrive}">Xem OneDrive</a>\n` : ''}\u2514 \ud83d\udd17 <a href="${clickupUrl}">Xem trong ClickUp</a>`
  );
};

let messages = [];
if (all.length === 0) {
  messages.push({ json: { chatId, beautified: `\u274c Kh\u00f4ng t\u00ecm th\u1ea5y k\u1ebft qu\u1ea3 n\u00e0o ph\u00f9 h\u1ee3p v\u1edbi t\u1eeb kh\u00f3a <b>${escapeHtml(searchText)}</b>`, messageId, parse_mode: "HTML" } });
} else {
  const headerMessage = `\ud83d\udd0d <b>K\u1ebft qu\u1ea3 t\u00ecm ki\u1ebfm: ${escapeHtml(searchText)}</b>\nT\u00ecm th\u1ea5y ${all.length} k\u1ebft qu\u1ea3:`;
  messages.push({ json: { chatId, beautified: headerMessage, messageId, parse_mode: "HTML" } });
  const combined = [...fullMatches, ...partialMatches];
  combined.forEach((task, index) => {
    messages.push({ json: { chatId, beautified: formatTask(task, index), messageId: null, parse_mode: "HTML" } });
  });
}
return messages;

const inputItems = $input.all();
const originalContext = inputItems.find(i => i.json.chatId);
const chatId = originalContext?.json?.chatId || null;
const messageId = originalContext?.json?.messageId || null;
const all = inputItems.filter(i => i.json.id).map(i => i.json);
const botUsername = 'Elite_clickup_bot';

const escapeHtml = (text) => text?.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;') || '';
const cleanLink = (link) => {
  if (!link) return '';
  return link.replace(/^'+|'+$/g, '').replace(/^\(+|\)+$/g, '').replace(/[{}]/g, '').trim();
};

const task = all[0] || {};
const link = `https://t.me/${botUsername}?start=chitiet_${task.id}`;
const lines = [];
lines.push(`<b>${escapeHtml(task.name)}</b>`);
lines.push(`\u251c Mi\u00eau t\u1ea3: ${escapeHtml(task.description?.trim()) || 'Kh\u00f4ng r\u00f5'}`);
lines.push(`\u251c Tr\u1ea1ng th\u00e1i: ${escapeHtml(task.status || 'Kh\u00f4ng r\u00f5')}`);
lines.push(`\u251c List: ${task.list ? escapeHtml(task.list) : 'Kh\u00f4ng r\u00f5'}`);
lines.push(`\u251c Ph\u1ee5 tr\u00e1ch: ${escapeHtml(task.phu_trach?.trim()) || 'Kh\u00f4ng r\u00f5'}`);
if (task.DKPV) lines.push(`\u251c \u0110\u0103ng k\u00ed ph\u1ecfng v\u1ea5n: ${escapeHtml(task.DKPV)}`);
if (task.PVTC) lines.push(`\u251c Ph\u1ecfng v\u1ea5n th\u00e0nh c\u00f4ng: ${escapeHtml(task.PVTC)}`);
if (task.onedrive_link) {
  lines.push(`\u251c \ud83d\udcc1 <a href="${cleanLink(task.onedrive_link)}">Xem OneDrive</a>`);
}
if (task.youtube_link) {
  lines.push(`\u251c \ud83c\udfde\ufe0f Video: ${task.youtube_link}`);
}
lines.push(`\u2514 \ud83d\udd17 <a href="${cleanLink(task.url)}">Xem trong ClickUp</a>`);

return [{
  json: {
    beautified: lines.join('\n'),
    chatId, messageId, parse_mode: "HTML",
    taskId: task.id || null,
    hasOnedriveLink: !!task.onedrive_link
  }
}];

// Chuan hoa OneDrive share link thanh dinh dang Graph API can (u!<base64url>)
// Tham khao: https://learn.microsoft.com/en-us/graph/api/shares-get
const items = $input.all();
function encodeSharingUrl(url) {
  const b64 = Buffer.from(url, 'utf-8').toString('base64');
  return 'u!' + b64.replace(/=+$/, '').replace(/\//g, '_').replace(/\+/g, '-');
}
return items.map(it => {
  const raw = (it.json.onedrive_link || '').replace(/[{}]/g, '').replace(/^'+|'+$/g, '').trim();
  return {
    json: {
      ...it.json,
      onedriveUrlClean: raw,
      encodedShareId: raw ? encodeSharingUrl(raw) : null
    }
  };
});

// Dung item cua 'Phan tich lenh' de lay chatId (khong phai item hien tai, vi item hien tai la Graph API response)
const chatId = $('Phân tích lệnh').item.json.chatId;
const item = $json;

const escapeHtml = (t) => (t || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

let text = '';
let buttons = [];

if (item.error) {
  text = '\u26a0\ufe0f Kh\u00f4ng th\u1ec3 m\u1edf link OneDrive c\u1ee7a task n\u00e0y (link l\u1ed7i ho\u1eb7c \u0111\u00e3 h\u1ebft h\u1ea1n chia s\u1ebb).';
} else if (item.folder && Array.isArray(item.children) && item.children.length > 0) {
  text = `\ud83d\udcc1 <b>${escapeHtml(item.name)}</b>\nB\u1ea5m v\u00e0o t\u00ean file \u0111\u1ec3 t\u1ea3i v\u1ec1 (link t\u1ea3i c\u00f3 hi\u1ec7u l\u1ef1c t\u1ea1m th\u1eddi):`;
  buttons = item.children
    .filter(c => c.file) // chi lay file, bo qua sub-folder o phien ban dau
    .slice(0, 20) // gioi han so nut tranh tin nhan qua dai
    .map(c => ({
      text: c.name,
      additionalFields: { url: c['@microsoft.graph.downloadUrl'] || c.webUrl }
    }));
  if (buttons.length === 0) {
    text += '\n\n(Th\u01b0 m\u1ee5c ch\u1ec9 ch\u1ee9a th\u01b0 m\u1ee5c con, ch\u01b0a h\u1ed7 tr\u1ee3 li\u1ec7t k\u00ea \u0111\u1ec7 quy \u1edf b\u1ea3n n\u00e0y.)';
  }
} else if (item.file) {
  text = `\ud83d\udcc4 <b>${escapeHtml(item.name)}</b>`;
  buttons = [{ text: '\u2b07\ufe0f T\u1ea3i file', additionalFields: { url: item['@microsoft.graph.downloadUrl'] || item.webUrl } }];
} else {
  text = '\u26a0\ufe0f Kh\u00f4ng x\u00e1c \u0111\u1ecbnh \u0111\u01b0\u1ee3c n\u1ed9i dung OneDrive c\u1ee7a task n\u00e0y.';
}

// Telegram gioi han 8 nut/hang -> xep moi hang 1 nut cho ten file dai de de doc
const rows = buttons.map(b => ({ row: { buttons: [b] } }));

return [{
  json: { chatId, text, rows, hasButtons: rows.length > 0 }
}];

const folders = $input.all().map(i => i.json);
const rows = folders.slice(0, 30).map(f => ({
  row: { buttons: [{ text: f.name, additionalFields: { callback_data: `sync_folder:${f.id}` } }] }
}));
const text = folders.length > 0
  ? '📁 Chọn Folder muốn đồng bộ:'
  : '⚠️ Không tìm thấy Folder nào trong Space.';
return [{ json: { chatId: $('Phân tích lệnh').first().json.chatId, text, rows, hasButtons: rows.length > 0 } }];

const folderId = $('Phân tích lệnh').first().json.params;
const lists = $input.all().map(i => i.json);
const rows = lists.slice(0, 30).map(l => ({
  row: { buttons: [{ text: l.name, additionalFields: { callback_data: `sync_list:${l.id}:${folderId}` } }] }
}));
const text = lists.length > 0
  ? '📋 Chọn List muốn đồng bộ:'
  : '⚠️ Folder này không có List nào.';
return [{ json: { chatId: $('Phân tích lệnh').first().json.chatId, text, rows, hasButtons: rows.length > 0 } }];

// params dang "<list_id>:<folder_id>"
const raw = $('Phân tích lệnh').first().json.params;
const [listId, folderId] = raw.split(':');
return [{ json: { listId, folderId } }];

const info = $('Tách List ID + Folder ID').first().json;
const listData = $json; // tu ClickUp - Get List Info
return [{
  json: {
    list_id: info.listId,
    list_name: listData.name || '',
    folder_id: info.folderId,
    folder_name: listData.folder?.name || '',
    added_by: String($('Phân tích lệnh').first().json.chatId),
  }
}];

const t = $json; // { list_id, list_name, ... } tu ket qua upsert
const chatId = $('Phân tích lệnh').first().json.chatId;
const text = `✅ Đã lưu List "<b>${t.list_name}</b>" vào danh sách tự động đồng bộ (mỗi 5 ngày).\n\nĐồng bộ ngay bây giờ luôn không?`;
const rows = [{ row: { buttons: [
  { text: '⚡ Đồng bộ ngay', additionalFields: { callback_data: `sync_now:${t.list_id}` } },
  { text: '⏳ Chờ lần sau', additionalFields: { callback_data: 'sync_later' } },
] } }];
return [{ json: { chatId, text, rows } }];
